// ColorSwatch, AS GRAPH SOURCE (#3660, epic #3604) — a pure leaf shared/ui primitive authored as DATA. Its
// `provides: "@/shared/ui/controls/ColorSwatch"` makes the runtime loader vendor THIS source wherever a graph component imports
// that specifier, so the primitive renders from the graph, not bundled code (registered code is the
// fallback when no component provides it). Transcribed verbatim from the live .tsx; deps (Skeleton/Card/
// math) stay registered code — a fresh compile is safe because the primitive holds no context or state.
import type { CSSProperties } from "react";

export interface ColorSwatchProps {
  /** The fill colour — any CSS colour, incl. `var()` / `color-mix()`. */
  color: string;
  /** Square side in px. Default 9. */
  size?: number;
  /** Corner radius in px. Default 2. */
  radius?: number;
  className?: string;
  style?: CSSProperties;
}

/** ColorSwatch — the small rounded colour square used as a category / profile / legend indicator.
 *  Replaces the inline `<span style={{ width:9, height:9, borderRadius:2, background }} />` repeated
 *  across the app. `flex:0 0` keeps it from shrinking inside flex rows. */
export function ColorSwatch({ color, size = 9, radius = 2, className, style }: ColorSwatchProps) {
  return (
    <span
      className={className}
      style={{ display: "inline-block", width: size, height: size, borderRadius: radius, background: color, flex: `0 0 ${size}px`, ...style }}
    />
  );
}

